"""Build findings and limitations strictly from script-produced JSON files."""
from pathlib import Path
import json
HERE=Path(__file__).resolve().parent
def read(n):return json.loads((HERE/n).read_text())
def write(n,d):(HERE/n).write_text(json.dumps(d,indent=2,allow_nan=False)+'\n')
def pct(x):return f'{100*x:.1f}%'
def main():
    D,F,H,R,S=map(read,['ozturkoglu_extract.json','frp_results.json','h1_h2_results.json','retrofit_signal_results.json','digitised_static.json'])
    primary=[r for r in F['strengthened'] if r['representation']=='fiber_equivalent']; pre=[r for r in primary if 'Pre' in r['beam']];post0=[r for r in primary if r['initial_strain_case']=='ignore_initial_strain'];postr=[r for r in primary if r['initial_strain_case']=='residual_global_curvature_proxy']
    kap=H['H2']['fits']['mode1'];kap2=H['H2']['fits']['mode2'];h1=H['H1'];t=H['twin']['gap_1_damage_levels']['pooled'];m=H['H2']['Musial_reference'];v1=[r for r in R['rows'] if r['direction']=='vertical' and r['mode']==1];c1=H['H2']['counts']['mode1']['counterexamples'][0]
    minpre=min(r['ultimate']['predicted_to_test'] for r in pre);maxpre=max(r['ultimate']['predicted_to_test'] for r in pre)
    numerical_consistency=[]
    for r in S['rows']:
        if r['beam']=='CFRP_PreStr' and r['stage']=='D1':
            tab=D['static'][r['beam']]['ultimate_load_kN']['value']
            numerical_consistency.append(dict(beam=r['beam'],figure_endpoint_load_kN=r['load_kN'],table_ultimate_load_kN=tab,difference_kN=tab-r['load_kN'],status='SOURCE_DISCREPANCY_RETAINED',reason='Figure 4 near D1 reads below Table 4 peak; capacity comparison uses table, secant analysis uses figure. This discrepancy is larger than the pure pixel reading bound.'))
        if r['beam']=='GFRP_PreStr' and r['stage']=='D2':
            tab=D['static'][r['beam']]['ultimate_load_kN']['value']
            numerical_consistency.append(dict(beam=r['beam'],figure_endpoint_load_kN=r['load_kN'],table_ultimate_load_kN=tab,difference_kN=r['load_kN']-tab,status='SOURCE_DISCREPANCY_RETAINED',reason='Later figure plateau exceeds tabulated ultimate. No rescaling applied.'))
    summary=dict(job='B1',paper_year=D['paper']['year'],doi=D['paper']['doi'],status='COMPLETED_WITH_SCIENTIFIC_LIMITATIONS',number_of_beams=kap['n_beams'],matched_beam_steps=kap['n_beam_steps'],capacity_status='CONDITIONAL_FIBER_EQUIVALENT_INPUTS_NO_COUPONS',prestrengthened_ultimate= [{'beam':r['beam'],'predicted_kN':r['ultimate']['P_jack_kN'],'test_kN':r['ultimate']['test_P_kN'],'predicted_to_test':r['ultimate']['predicted_to_test']} for r in pre],prestrengthened_yield=[{'beam':r['beam'],'predicted_kN':r['yield_prediction']['P_jack_kN'],'test_kN':r['yield_prediction']['test_P_kN'],'predicted_to_test':r['yield_prediction']['predicted_to_test']} for r in pre],poststrengthened_initial_strain_cases=[{'beam':r['beam'],'case':r['initial_strain_case'],'predicted_kN':r['ultimate']['P_jack_kN'],'predicted_to_test':r['ultimate']['predicted_to_test']} for r in primary if 'Post' in r['beam']],kappa=kap['pooled'],kappa_95_interval=kap['bootstrap_95_interval'],kappa_mode2=kap2['pooled'],kappa_definition='Frequency-squared loss versus large-displacement envelope secant loss; baseline is first-crack secant.',kappa_bootstrap_unit='beam',kappa_directly_poolable_with_service_stiffness=False,H1_status=h1['status'],H1_dynamic_spread_percentage_points=h1['vibration_mode1_spread_percentage_points'],H2_vibration_larger=H['H2']['counts']['mode1']['vibration_larger'],H2_counterexamples=H['H2']['counts']['mode1']['counterexamples'],twin_predictions=t['n_predictions'],twin_median_error_bias_pct=t['median_abs_error_pct']['bias_learning'],twin_median_error_hold_pct=t['median_abs_error_pct']['hold_last_check'],twin_median_error_vibration_pct=t['median_abs_error_pct']['vibration_no_bias'],twin_scope='Consecutive envelope-secant proxy, not service-deflection validation.',retrofit_vertical_mode1_change_pct={r['beam']:r['frequency_change_pct'] for r in v1},retrofit_static_check_required=True,source_discrepancies=numerical_consistency,human_needed_items=D['missing'],report_numeric_sources=['ozturkoglu_extract.json','frp_results.json','h1_h2_results.json','retrofit_signal_results.json','digitised_static.json'],figures=['01_capacity_predicted_vs_test.png','02_static_vs_vibration.png','03_retrofit_vertical_signal.png'])
    write('results_summary.json',summary)
    labels={'GFRP_PreStr':'Glass fiber, before damage','CFRP_PreStr':'Carbon fiber, before damage','GFRP_PostStr':'Glass fiber, after damage','CFRP_PostStr':'Carbon fiber, after damage'}
    L=[f'# Job B1: independent published beam benchmark ({D["paper"]["year"]})','',
       '## Findings first','',
       f'- **Ultimate capacity, conditional:** pre-strengthened predictions are {pre[0]["ultimate"]["P_jack_kN"]:.2f} and {pre[1]["ultimate"]["P_jack_kN"]:.2f} kN against {pre[0]["ultimate"]["test_P_kN"]:.2f} and {pre[1]["ultimate"]["test_P_kN"]:.2f} kN; conservative by {100*(1-maxpre):.1f}% to {100*(1-minpre):.1f}%. Fiber-equivalent thickness is inferred, so this is conditional agreement.',
       f'- **Yield prediction is poorer:** steel-strain yield predictions are {pre[0]["yield_prediction"]["P_jack_kN"]:.2f} and {pre[1]["yield_prediction"]["P_jack_kN"]:.2f} kN, {100*(1-pre[0]["yield_prediction"]["predicted_to_test"]):.1f}% and {100*(1-pre[1]["yield_prediction"]["predicted_to_test"]):.1f}% below the paper\'s equivalent elasto-plastic yields. Different yield definitions limit the comparison.',
       f'- **Post-strengthened capacity:** ignoring initial strain gives {post0[0]["ultimate"]["P_jack_kN"]:.2f} and {post0[1]["ultimate"]["P_jack_kN"]:.2f} kN; the residual-curvature proxy gives {postr[0]["ultimate"]["P_jack_kN"]:.2f} and {postr[1]["ultimate"]["P_jack_kN"]:.2f} kN. Local residual substrate strain is not identified.',
       f'- **Vibration versus static secant:** kappa = {kap["pooled"]:.3f}, beam-bootstrap 95% interval {kap["bootstrap_95_interval"][0]:.3f} to {kap["bootstrap_95_interval"][1]:.3f}; overlaps Musial\'s {m["kappa_compliance_corrected"]:.3f} to {m["kappa_raw"]:.3f}. Vibration stiffness is larger in {H["H2"]["counts"]["mode1"]["vibration_larger"]} of {kap["n_beam_steps"]} comparisons. This secant includes plastic displacement.',
       f'- **Identical bare beams at D1:** vibration stiffness indices are {pct(h1["rows"][0]["vibration_mode1_left"])} and {pct(h1["rows"][1]["vibration_mode1_left"])}, a {h1["vibration_mode1_spread_percentage_points"]:.2f} percentage-point spread. D1 fixes displacement, so equal-load H1 is not demonstrated.',
       f'- **Twin test is not a service-accuracy confirmation:** over {t["n_predictions"]} consecutive predictions, median absolute proxy-deflection error is {t["median_abs_error_pct"]["bias_learning"]:.1f}% with bias learning, {t["median_abs_error_pct"]["hold_last_check"]:.1f}% holding the last check and {t["median_abs_error_pct"]["vibration_no_bias"]:.1f}% from vibration alone.',
       f'- **Vibration sees an inconsistent repair signal:** first vertical frequency changes by {v1[0]["frequency_change_pct"]:+.2f}% after glass-fiber strengthening and {v1[1]["frequency_change_pct"]:+.2f}% after carbon-fiber strengthening. A matched static load and deflection check is required to confirm repair.',
       '', 'All numerical findings are generated from the JSON files named at the end. No input was adjusted to match the tests.','',
       '## Specimens and source extraction','',
       f'Ozturkoglu and colleagues studied {kap["n_beams"]} nominally identical beams. The section is {D["geometry"]["width_mm"]["value"]} by {D["geometry"]["height_mm"]["value"]} mm, with {D["geometry"]["span_mm"]["value"]} mm span and {D["geometry"]["shear_span_mm"]["value"]} mm shear span. Mean cylinder concrete strength is approximately {D["concrete"]["cylinder_strength_MPa"]["value"]} MPa. Steel yield, tensile strength and modulus are {D["steel"]["yield_MPa"]["value"]} MPa, {D["steel"]["tensile_MPa"]["value"]} MPa and {D["steel"]["modulus_MPa"]["value"]/1000:g} GPa. The paper states steel and fiber properties without individual coupon results.',
       '',f'The extraction records source pages, tables and figures for every value, and marks inferred and missing inputs. {D["read_audit"]["table_numeric_values_checked"]} numeric table entries were checked between the layout text and an independent rendered-page transcription. The text layer contains duplicate and joined entries. Exact decimal substrings plus the visual read resolve those entries; the original strict token-boundary failure is retained. This lexical check alone is not a table-cell parser.',
       '', '## Strengthening capacity method','',
       f'The section uses the unchanged parabola-rectangle concrete and elastic-perfectly-plastic steel logic from `val_frp.py`, with {F["method"]["concrete_slices"]} concrete slices and {F["method"]["neutral_axis_grid_points"]} trial neutral-axis depths. Concrete peak and ultimate strains are {F["method"]["eps_c2"]:g} and {F["method"]["eps_cu"]:g}. The supplied American Concrete Institute guide debonding formula is `{F["method"]["eps_fd_formula"]}`. No safety or strength reduction factors are used. Jack load follows the specimen\'s four-point arrangement and subtracts self-weight moment.',
       '',f'Self-weight uses an assumed unit weight of {F["assumed_self_weight"]["unit_weight_kN_m3"]:g} kN/m3 and a nominal modulus proxy of {F["assumed_self_weight"]["Ec_MPa"]/1000:.2f} GPa. The self-weight moment is {F["assumed_self_weight"]["M_self_weight_kNm"]:.4f} kN m and initial soffit strain is {F["assumed_self_weight"]["initial_substrate_strain"]:.6f}. Neither density nor concrete modulus is measured in the paper.',
       '', '### Fiber modulus must use a compatible thickness','',
       '| Material | Wet total thickness (mm) | Fiber volume | Inferred fiber-equivalent total (mm) | Fiber modulus (GPa) | Derived rupture strain | Debonding limit |','|---|---:|---:|---:|---:|---:|---:|']
    for mat,mtr in D['strengthening'].items():
        inp=next(r for r in F['material_inputs'][mat] if r['representation']=='fiber_equivalent')
        L.append(f'| {"Glass fiber" if mat=="GFRP" else "Carbon fiber"} | {mtr["wet_laminate_total_thickness_mm"]["value"]:.1f} | {pct(mtr["fiber_volume_fraction"]["value"])} | {inp["total_effective_thickness_mm"]:.3f} | {inp["Ef_MPa"]/1000:g} | {inp["eps_fu"]:.5f} | {inp["eps_fd"]:.5f} |')
    L += ['', 'The primary mapping treats total fiber volume as longitudinal effective area and neglects resin load contribution. It is an input assumption, not a measured composite property. A second sensitivity uses only the dominant-direction fiber mass fraction, whose alignment along the beam is not confirmed. A cured axial coupon would resolve the basis. The reported thickness is already the total laminate thickness; it is not multiplied again by the number of layers.','', 'No U-wrap or independent anchorage is reported. A wrap strain limit is therefore inapplicable. The official guide preview confirms the guide and anchorage scope but does not expose the full equation clause. The equation comes from the supplied job and frozen method; full guide compliance is not claimed.','', '### Conditional predictions and retained failures','', '| Beam and strain assumption | Predicted ultimate (kN) | Test ultimate (kN) | Predicted/test | Predicted steel yield (kN) | Test yield (kN) | Yield ratio |','|---|---:|---:|---:|---:|---:|---:|']
    for r in primary:
        u,y=r['ultimate'],r['yield_prediction'];testy='unreported' if y['test_P_kN'] is None else f'{y["test_P_kN"]:.2f}';yr='unavailable' if y['predicted_to_test'] is None else f'{y["predicted_to_test"]:.3f}';py='limit first' if y['P_jack_kN'] is None else f'{y["P_jack_kN"]:.2f}'
        L.append(f'| {labels[r["beam"]]}, {r["initial_strain_case"].replace("_"," ")} | {u["P_jack_kN"]:.2f} | {u["test_P_kN"]:.2f} | {u["predicted_to_test"]:.3f} | {py} | {testy} | {yr} |')
    L += ['', 'The model predicts first steel-strain yield, whereas the paper determines an equivalent elasto-plastic yield from reduced stiffness. This definition mismatch, unreported coupon variation and cyclic response may explain poor yield agreement. No parameter was changed to improve it. Post-strengthened yield is not separately reported; the bare-stage yield must not be reused as a repaired yield.','', '| Material-basis diagnostic, before damage | Predicted ultimate (kN) | Predicted/test | Status |','|---|---:|---:|---|']
    for r in F['strengthened']:
        if 'Pre' in r['beam'] and r['representation']!='fiber_equivalent':
            L.append(f'| {labels[r["beam"]]}, {r["representation"].replace("_"," ")} | {r["ultimate"]["P_jack_kN"]:.2f} | {r["ultimate"]["predicted_to_test"]:.3f} | {"Invalid fiber/gross pairing, retained" if r["representation"]=="gross_thickness_diagnostic" else "Conditional orientation sensitivity"} |')
    L += ['', '### Initial strain after damage','', 'The post-strengthened beams were already past their bare yield and retained permanent displacement. The second calculation uses a residual global-curvature proxy. It assigns the elastic four-point deflection shape to that residual displacement, and uses the bare steel-yield neutral axis to convert curvature to soffit strain. This is not the actual residual strain state. The American Concrete Institute elastic substrate treatment cannot represent yielded steel, local hinges, crushing or bond degradation.','', '| Beam | Residual displacement proxy (mm) | Reading bound (mm) | Initial substrate strain proxy |','|---|---:|---:|---:|']
    for b,r in F['residual_state_proxies'].items():L.append(f'| {labels[b]} | {r["residual_displacement_mm"]:.2f} | +/-{r["reading_uncertainty_mm"]:.1f} | {r["substrate_strain_proxy"]:.5f} |')
    L += ['', 'Both zero-offset and residual-proxy results remain in the results file. Neither is promoted to an identified damaged-section prediction. Residual displacement alone cannot determine the neutral-axis location or plastic curvature distribution.','', '### Bare beam check','',F['method']['IS456_bare'], '', '| Bare beam | Predicted ultimate (kN) | Observed bare peak (kN) | Predicted/test | Predicted yield/test |','|---|---:|---:|---:|---:|']
    for r in F['bare']:L.append(f'| {labels[r["beam"]]} | {r["IS456_shape_ultimate"]["P_jack_kN"]:.2f} | {r["test_ultimate_kN"]:.2f} | {r["ultimate_predicted_to_test"]:.3f} | {r["yield_predicted_to_test"]:.3f} |')
    L += ['', 'The bare trials stopped for repair. Their observed peaks are not independent bare failure capacities. An additional direct-cylinder parabola-rectangle result is retained in the JSON to expose the strength-basis difference.','', f'![Capacity predictions]({HERE/"01_capacity_predicted_vs_test.png"})','', '## Vibration versus damage','', 'Vibration stiffness index is the squared frequency ratio. Static stiffness is the envelope load divided by imposed displacement, normalized to the first-crack load/displacement secant. This includes permanent deformation and is not a reloading tangent or an independently measured service stiffness. Dynamic testing was unloaded with the jack detached, but residual deformation remained. The quantities answer different physical questions.','', 'The pixel method calibrates the outer plot frame and grid ticks, selects the colored or black loading plateau and saves an overlay. Slightly left-of-target readings avoid vertical cycle drops. The carbon bare D1 plateau is obscured at the target, so the nearest clear flat segment is used with a larger displacement reading bound.','', f'Typical reading bounds are +/-{S["reading_uncertainty"]["load_kN"]:.1f} kN and +/-{S["reading_uncertainty"]["displacement_mm"]:.1f} mm; the carbon bare D1 displacement bound is +/-{next(r["reading_uncertainty_displacement_mm"] for r in S["rows"] if r["beam"]=="CFRP_PostStr" and r["stage"]=="D1"):.1f} mm. These are reading bounds, not confidence intervals. Baseline-proxy reading sensitivity is propagated separately from beam-bootstrap uncertainty.','', '| Beam | Stage | Condition | Load from figure (kN) | Static secant left | Vertical mode one left | Vertical mode two left |','|---|---|---|---:|---:|---:|---:|']
    for r in H['rows']:L.append(f'| {labels[r["beam"]]} | {r["stage"]} | {r["condition"]} | {r["load_kN"]:.2f} | {pct(r["static_left"])} | {pct(r["vibration_mode1_left"])} | {pct(r["vibration_mode2_left"])} |')
    L += ['',f'The retained counterexample is {labels[c1["beam"]]} at {c1["stage"]}: static secant left {pct(c1["static_left"])} versus vibration left {pct(c1["vibration_left"])}. The difference is small relative to source-reading and stiffness-definition uncertainty; no universal ordering is established.','', '### Kappa fit and uncertainty','',f'Loss ratios are fitted through the origin. The bootstrap resamples {kap["n_beams"]} beam clusters with all their steps, using {kap["bootstrap_draws"]} draws and seed {kap["bootstrap_seed"]}. The sample is small, combines different strengthening histories and has unequal numbers of steps.','', '| Vibration mode | Pooled kappa | Beam-bootstrap 95% interval |','|---|---:|---|',f'| Vertical first | {kap["pooled"]:.3f} | {kap["bootstrap_95_interval"][0]:.3f} to {kap["bootstrap_95_interval"][1]:.3f} |',f'| Vertical second | {kap2["pooled"]:.3f} | {kap2["bootstrap_95_interval"][0]:.3f} to {kap2["bootstrap_95_interval"][1]:.3f} |','', '| Beam | First-mode kappa | Matched levels |','|---|---:|---:|']
    for b,r in kap['per_beam'].items():L.append(f'| {labels[b]} | {r["kappa"]:.3f} | {r["n_steps"]} |')
    L += ['',f'Assigning all static ratios to their low or high source-reading bounds changes first-mode kappa to {kap["source_reading_extremes"][0]:.3f} and {kap["source_reading_extremes"][1]:.3f}. This sensitivity is not included in the beam-bootstrap interval. The interval also excludes bias from baseline choice, plastic deformation, mass changes and source discrepancies.', '', f'The earlier Musial raw and compliance-corrected results are {m["kappa_raw"]:.3f} and {m["kappa_compliance_corrected"]:.3f}. The central value here is compatible with that range, but agreement of different secant/tangent definitions does not establish a transferable calibration. Keep this series separate in any pooled table and label its stiffness definition.', '', '### Source discrepancies kept','']
    for r in numerical_consistency:L.append(f'- {labels[r["beam"]]}: figure load {r["figure_endpoint_load_kN"]:.2f} kN versus tabulated ultimate {r["table_ultimate_load_kN"]:.2f} kN, difference {r["difference_kN"]:.2f} kN. {r["reason"]}')
    L += ['', 'Reloading and unloading readings were attempted and retained. Overlapping branches are not labelled by time or cycle direction clearly enough to establish the correct tangent at each modal state. They are excluded. Immediate after-bonding D1 frequencies also remain modal-only, with no fabricated static match.','', f'![Stiffness comparison]({HERE/"02_static_vs_vibration.png"})','', '## H1: nominally identical beams','',f'The two post-strengthened beams were bare at an imposed {h1["displacement_mm"]:g} mm D1 displacement. Their endpoint loads read {h1["load_kN"][0]:.2f} and {h1["load_kN"][1]:.2f} kN, and their static secant ratios are {pct(h1["rows"][0]["static_left"])} and {pct(h1["rows"][1]["static_left"])}. Their static spread is {h1["static_secant_spread_percentage_points"]:.2f} percentage points, with overlapping reading bounds. The vibration spread is {h1["vibration_mode1_spread_percentage_points"]:.2f} percentage points. Nominally equal specimens do differ, but the protocol does not supply vibration measurements at a matched load, so equal-load H1 remains untested here.','', '## Twin bias-learning check','', 'At the previous measured state, learn the logarithm of vibration stiffness divided by static stiffness. At the next state, multiply the new vibration stiffness by the exponential of the negative previous bias. Deflection-proxy error is true stiffness divided by predicted stiffness, minus unity. Holding the last static check and normalized vibration alone are the baselines. This is the same algebra as the existing test. Consecutive damage-level gaps replace its load gaps; no calibration uses a target-stage measurement.','', 'Only strengthened histories with enough matched stages are used. No prediction crosses the bare-to-repaired intervention. Error bounds from static reading and frequency rounding are stored for every prediction.','', '| Check spacing | Predictions | Median bias-learning error | Median hold error | Median vibration-only error | Maximum bias-learning error |','|---|---:|---:|---:|---:|---:|']
    for name,tr in H['twin'].items():
        p=tr['pooled'];L.append(f'| {name.replace("_"," ")} | {p["n_predictions"]} | {p["median_abs_error_pct"]["bias_learning"]:.1f}% | {p["median_abs_error_pct"]["hold_last_check"]:.1f}% | {p["median_abs_error_pct"]["vibration_no_bias"]:.1f}% | {p["max_abs_error_pct"]["bias_learning"]:.1f}% |')
    L += ['', 'These errors concern an implied deflection at equal diagnostic force derived from successive large-displacement secants. They are not measured service-deflection predictions. Learning the bias helps against vibration alone, but it does not establish the earlier service-accuracy target in this series.','', '## Can vibration confirm the retrofit?','', '| Beam | Direction | Mode | Frequency change | Apparent squared-frequency change |','|---|---|---:|---:|---:|']
    for r in R['rows']:L.append(f'| {labels[r["beam"]]} | {r["direction"]} | {r["mode"]} | {r["frequency_change_pct"]:+.2f}% | {r["apparent_frequency_squared_change_pct"]:+.2f}% |')
    L += ['', 'Changes use the after/before D1 frequency-ratio quotient, not the difference between their ratios to the undamaged state. Printed-ratio rounding bounds are provided in the result file. Measurement repeatability is not reported, so small changes are not assigned statistical significance.','']
    for b,r in R['static_capacity_gain'].items():L.append(f'- {labels[b]}: observed peak capacity rises from {r["bare_observed_peak_kN"]:.2f} to {r["strengthened_observed_peak_kN"]:.2f} kN, a {r["gain_pct"]:.2f}% gain. This is capacity gain, not immediate static-stiffness recovery.')
    mc=R['Musial_context'];L += ['',f'The supplied Musial context reports frequency gains of about {mc["frequency_gain_pct"][0]}% to {mc["frequency_gain_pct"][1]}% against static-stiffness gains of about {mc["static_stiffness_gain_pct"][0]}% to {mc["static_stiffness_gain_pct"][1]}%. Those approximate ranges are carried from the job context, not newly extracted. Here even the sign of the vertical signal depends on the strengthening material. The paper proposes transport and curing under self-weight as possible explanations. A frequency change can show a change of state, but a static check is needed to verify useful repair.','', f'![Retrofit signal]({HERE/"03_retrofit_vertical_signal.png"})','', '## Limitations and human evidence needed','']
    L += ['- '+r for r in D['missing']]
    L += ['', 'The requested numerical analyses and reproducible outputs are complete within these limits. Unconditional capacity validation, an identified post-yield residual-state prediction, equal-load H1, reloading stiffness and service-deflection validation remain unavailable. No slide deck, workbook, parent review README or ReBuild file is updated.','', '## Files and provenance','', '`ozturkoglu_extract.json`: sourced inputs and missing fields. `frp_results.json`: every capacity scenario, strain state and force residual. `digitised_static.json`: pixels, axes, bounds and excluded reads. `h1_h2_results.json`: paired ratios, cluster bootstrap and twin rows. `retrofit_signal_results.json`: every modal repair change. `results_summary.json`: headlines with pooling and scope flags. `QA.json` and `manifest.json`: execution and integrity checks. `RUN.md`: rerun instructions.','',f'Source: [Ozturkoglu and colleagues, Applied Sciences, {D["paper"]["year"]}](https://doi.org/{D["paper"]["doi"]}). Source pages and figure overlays reproduce the open-access paper under its Creative Commons Attribution license. Source PDF SHA-256: `{D["paper"]["sha256"]}`.','',f'Method reference: [American Concrete Institute guide preview]({F["method"]["ACI_reference"]["url"]}); the full equation clause was not independently available. Existing Musial results and code are preserved as hashed read-only snapshots.','']
    report='\n'.join(L)
    assert '\u2014' not in report
    (HERE/'REPORT.md').write_text(report)
    needed=['# Human evidence needed','', 'The scripts have run. The following scientific inputs cannot be recovered reliably from the paper and need author data, a source document or engineering review:','']+['- '+r+'.' for r in D['missing']]+['- Provide labelled raw cyclic load-displacement histories if a reliable unloading/reloading tangent is required.','- Provide matched service-load static checks if the twin\'s service-deflection claim is to be evaluated.','- Provide the full licensed American Concrete Institute flexural clause for a clause-by-clause compliance audit; the supplied equation and frozen method were used as authorized.','', 'The residual-curvature scenario is explicitly a proxy. It does not replace the missing residual strain field. No human response is needed to rerun the delivered analysis.']
    (HERE/'HUMAN_NEEDED.md').write_text('\n'.join(needed)+'\n')
    print('Wrote REPORT.md, HUMAN_NEEDED.md and results_summary.json.')

if __name__=='__main__':main()
